command:
// Foundry VTT Macro: ремонт бестиария — естественное оружие + пересинхронизация
// вложенных предметов акторов с компендиумами.
//
// ФАЗА 1 (компендиум оружия):
//   - `fangs` и `strong_fangs` получают `skill: "unarmed_combat"`. Сейчас навык
//     пуст, а бросок атаки берёт навык с манёвра и только потом с оружия
//     (chat.mjs `rollAttack`). Поэтому манёвры без собственного навыка —
//     монстровая «Атака по возможности», «Атака с фланга», «Удар лапой» —
//     катились у зверей с рангом 0 вместо Безоружного боя.
//   - `paw` получает `properties.natural: true`. Без флага лапа — обычное оружие:
//     занимает руку (у медведя она и лежит в main_hand) и теоретически
//     обезоруживается, вопреки правилу «Естественное оружие» (18. Enemies).
//
// ФАЗА 2 (акторы `dedrel.actors`): вложенные копии предметов пересобираются из
// компендиума по `system.key`. Копии делались руками в разное время и отстали:
//   - у вожака волков и медведя ключи остались от переименования 2026-07-25
//     (`monster_pounce` вместо `maneuver_monster_pounce` и т.п.), поэтому цепи
//     (`chain_trigger_maneuvers` сверяются по `system.key`) не всплывают в HUD;
//   - талант «Вожак» на вожаке несёт `adds_items: ["monster_pack_howl"]` —
//     ссылка в пустоту;
//   - «Вой стаи» не помечен `parentItemId`, поэтому удаление таланта его не уносит.
// Ключ, которого больше нет, повторно ищется с префиксом `maneuver_` — этого
// достаточно для всех переименований 2026-07-25.
//
// Что сохраняется у вложенной копии (это состояние экземпляра, а не шаблона):
//   system.equipped, consume_target, quantity, uses_value, loaded,
//   flags.dedrel.isFavorite, flags.dedrel.parentItemId.
// Всё остальное (включая эффекты и adds_items) переписывается из компендиума.
//
// ФАЗА 3 (стат-блоки зверей, ревизия 2026-08-25): числа были собраны из
// разных строк таблицы целевых чисел (18. Enemies §«Целевые числа»):
//   - волк — ранг 1.5: ОД 6→5, Скорость 15→12 м;
//   - вожак — Скорость 15→12 м, текущие ОД/метры стояли в 0 (выходил на
//     стол без хода), нет предмета типа существа Beast;
//   - медведь — пеон ранга 3: hits 4→3 (правило пеона — 1–3), Прочность 5→6,
//     Безоружный бой 2→3 со специализацией (атака +5), общие Strong Fangs
//     заменяются на «Медвежью пасть» 2d6 (ступень III), чтобы не тянуть
//     вверх вожака волков, носящего те же клыки;
//   - копейщику и NPC template манёвры помечаются избранными: HUD цепей
//     показывает только избранное (chain-maneuvers-hud.mjs), иначе цепи мёртвы.
//
// ПОРЯДОК: сначала `import_bestiary_abilities_macro.js` (он создаёт «Полоснуть»
// и «Медвежью пасть»), потом этот макрос. Если новых сущностей ещё нет,
// макрос не ломается: ненайденное попадает в предупреждения, данные остаются как были.
//
// Идемпотентно: повторный прогон ничего не меняет. DRY_RUN=true — только отчёт.
(async () => {
  const DRY_RUN = false;
  const ACTOR_PACK = "dedrel.actors";

  const WEAPON_FIXES = [
    { key: "fangs", patch: { "system.skill": "unarmed_combat" } },
    { key: "strong_fangs", patch: { "system.skill": "unarmed_combat" } },
    { key: "paw", patch: { "system.properties.natural": true } }
  ];

  // Поля экземпляра, которые нельзя затирать шаблоном из компендиума
  const KEEP_SYSTEM = ["equipped", "consume_target", "quantity", "uses_value", "loaded"];

  // Явные переименования, которые не ловятся префиксом `maneuver_`.
  // «Удар лапой» был черновиком (0 ОД, пустое описание, опечатка в ключе)
  // и доведён до «Полоснуть» из BESTIARY_PLAN §3.
  const ALIASES = { manuver_paw_bash: "maneuver_monster_claw_slash" };

  // Стат-правки по итогам ревизии. patch — плоские пути для actor.update().
  const ACTOR_FIXES = {
    "Wolf": {
      patch: {
        "system.overrides.ap_max": 5,
        "system.overrides.movement_max": 12,
        "system.resources.ap_universal.value": 5,
        "system.resources.movement.value": 12,
        "system.details.threat": "1.5 (пеон)"
      }
    },
    "Wolf pack leader": {
      patch: {
        "system.overrides.movement_max": 12,
        "system.resources.ap_universal.value": 6,
        "system.resources.movement.value": 12,
        "system.details.threat": "2 (пеон)",
        "flags.dedrel.favoriteSkills": ["unarmed_combat", "perception", "atletism"]
      },
      addItems: ["beast"]
    },
    "Bear": {
      patch: {
        "system.resources.hits.value": 3,
        "system.resources.hits.max": 3,
        "system.toughness": 6,
        "system.skills.unarmed_combat.rank": 3,
        "system.skills.unarmed_combat.specialization": "Пасть",
        "system.resources.ap_universal.value": 6,
        "system.resources.movement.value": 12,
        "system.details.threat": "3 (пеон)"
      },
      replaceItems: { strong_fangs: "bear_maw" }
    },
    "Beast template": {
      patch: {
        "system.overrides.ap_max": 5,
        "system.overrides.movement_max": 12,
        "system.resources.ap_universal.value": 5,
        "system.resources.movement.value": 12
      }
    },
    // У этих двоих ни один манёвр не был избранным — HUD цепей молчал
    // Копейщик — единственный бандит без предмета типа существа: оружие
    // «против типа» на нём не срабатывало
    "Spearman bandit": { favoriteManeuvers: true, addItems: ["human"] },
    "NPC template": { favoriteManeuvers: true }
  };

  const log = [];
  const warn = [];

  // ==========================================================================
  // ФАЗА 1: компендиум оружия
  // ==========================================================================
  const weaponPack = game.packs.get("dedrel.weapons");
  if (!weaponPack) return ui.notifications.error("Компендиум dedrel.weapons не найден.");

  const weaponsLocked = weaponPack.locked;
  if (!DRY_RUN && weaponsLocked) await weaponPack.configure({ locked: false });

  const weaponDocs = await weaponPack.getDocuments();
  for (const fix of WEAPON_FIXES) {
    const doc = weaponDocs.find(w => w.system?.key === fix.key);
    if (!doc) { warn.push(`Оружие ${fix.key} в компендиуме не найдено`); continue; }
    const changed = Object.entries(fix.patch)
      .filter(([path, value]) => foundry.utils.getProperty(doc, path) !== value);
    if (!changed.length) continue;
    if (!DRY_RUN) await doc.update(fix.patch);
    log.push(`Оружие «${doc.name}»: ${changed.map(([p, v]) => `${p} = ${v}`).join(", ")}`);
  }

  if (!DRY_RUN && weaponsLocked) await weaponPack.configure({ locked: true });

  // ==========================================================================
  // ФАЗА 2: пересинхронизация предметов акторов
  // ==========================================================================
  // Индекс собираем ПОСЛЕ фазы 1, чтобы правки оружия уже уехали на листы.
  const index = new Map();
  for (const pack of game.packs) {
    if (pack.documentName !== "Item") continue;
    const idx = await pack.getIndex({ fields: ["system.key"] });
    for (const entry of idx) {
      const key = entry.system?.key;
      if (key && !index.has(key)) index.set(key, { pack, id: entry._id });
    }
  }

  const sourceCache = new Map();
  async function source(key) {
    if (sourceCache.has(key)) return sourceCache.get(key);
    const ref = index.get(key);
    const data = ref ? (await ref.pack.getDocument(ref.id)).toObject() : null;
    sourceCache.set(key, data);
    return data;
  }

  const actorPack = game.packs.get(ACTOR_PACK);
  if (!actorPack) return ui.notifications.error(`Компендиум ${ACTOR_PACK} не найден.`);

  const actorsLocked = actorPack.locked;
  if (!DRY_RUN && actorsLocked) await actorPack.configure({ locked: false });

  for (const actor of await actorPack.getDocuments()) {
    const updates = [];
    const renamed = [];
    const orphans = [];

    for (const item of actor.items) {
      const key = item.system?.key;
      if (!key) { orphans.push(`${item.name} (ключа нет)`); continue; }

      let data = ALIASES[key] ? await source(ALIASES[key]) : await source(key);
      let newKey = ALIASES[key] && data ? ALIASES[key] : key;
      if (ALIASES[key] && data) renamed.push(`${key} → ${newKey}`);
      if (!data && !key.startsWith("maneuver_")) {
        // Переименование 2026-07-25: весь компендиум манёвров уехал под префикс
        data = await source(`maneuver_${key}`);
        if (data) { newKey = `maneuver_${key}`; renamed.push(`${key} → ${newKey}`); }
      }
      if (!data) { orphans.push(`${item.name} (${key})`); continue; }

      const patch = { _id: item.id, name: data.name, img: data.img, system: data.system };
      for (const field of KEEP_SYSTEM) {
        const current = foundry.utils.getProperty(item, `system.${field}`);
        if (current !== undefined) patch.system[field] = current;
      }
      patch.flags = foundry.utils.mergeObject(data.flags ?? {}, {
        dedrel: {
          key: newKey,
          isFavorite: item.getFlag("dedrel", "isFavorite") ?? false,
          parentItemId: item.getFlag("dedrel", "parentItemId") ?? null
        }
      }, { inplace: false });

      // Обновляем, только если данные действительно разошлись
      const same = item.system.key === newKey
        && foundry.utils.objectsEqual(item.toObject().system, patch.system)
        && item.name === patch.name;
      if (!same) updates.push(patch);
    }

    if (updates.length && !DRY_RUN) {
      await actor.updateEmbeddedDocuments("Item", updates);
      // Эффекты переписываем отдельно: у них свои _id, обычный update их не трогает
      for (const patch of updates) {
        const item = actor.items.get(patch._id);
        const data = await source(item.system.key);
        if (!data) continue;
        const oldIds = item.effects.map(e => e.id);
        if (oldIds.length) await item.deleteEmbeddedDocuments("ActiveEffect", oldIds);
        if (data.effects?.length) {
          await item.createEmbeddedDocuments("ActiveEffect", foundry.utils.deepClone(data.effects), { keepId: true });
        }
      }
    }

    // --- Связь «талант/мутация → принесённые предметы» ---
    const wired = [];
    for (const parent of actor.items.filter(i => i.type === "talent" || i.type === "mutation")) {
      const keys = (parent.system.adds_items || [])
        .flatMap(entry => entry.split(";").map(s => s.trim()))
        .filter(Boolean);
      for (const key of keys) {
        const child = actor.items.find(i => i.system?.key === key);
        if (!child || child.getFlag("dedrel", "parentItemId") === parent.id) continue;
        if (!DRY_RUN) await child.setFlag("dedrel", "parentItemId", parent.id);
        wired.push(`${parent.name} → ${child.name}`);
      }
    }

    // --- Естественное оружие не занимает руки (18. Enemies) ---
    const freed = [];
    const slotPatch = {};
    for (const slot of ["main_hand", "off_hand"]) {
      const id = actor.system.equipment_slots?.[slot]?.item_id;
      if (!id) continue;
      const held = actor.items.get(id);
      if (held?.system?.properties?.natural) {
        slotPatch[`system.equipment_slots.${slot}.item_id`] = "";
        freed.push(`${held.name} из ${slot}`);
      }
    }
    if (Object.keys(slotPatch).length && !DRY_RUN) await actor.update(slotPatch);

    // ========================================================================
    // ФАЗА 3: стат-правки по итогам ревизии
    // ========================================================================
    const fix = ACTOR_FIXES[actor.name] ?? {};
    const stats = [];

    if (fix.patch) {
      const diff = Object.fromEntries(Object.entries(fix.patch)
        .filter(([path, value]) => !foundry.utils.objectsEqual(foundry.utils.getProperty(actor, path), value)));
      if (Object.keys(diff).length) {
        if (!DRY_RUN) await actor.update(diff);
        // Для путей вида resources.hits.max одного последнего сегмента мало
        const label = (path) => path.split(".").slice(-2).join(".").replace(/^system\./, "");
        stats.push(Object.entries(diff).map(([path, v]) => `${label(path)} → ${Array.isArray(v) ? v.join("/") : v}`).join(", "));
      }
    }

    // Замена предмета на другой (медведю — своя пасть вместо общих клыков):
    // экипировку переносим, чтобы зверь не остался безоружным.
    for (const [fromKey, toKey] of Object.entries(fix.replaceItems ?? {})) {
      const oldItem = actor.items.find(i => i.system?.key === fromKey);
      if (!oldItem) continue;
      const data = await source(toKey);
      if (!data) { warn.push(`${actor.name}: замена ${fromKey} → ${toKey} невозможна, ключа нет в компендиумах`); continue; }
      if (!DRY_RUN) {
        const payload = foundry.utils.deepClone(data);
        payload.system.equipped = oldItem.system.equipped ?? true;
        delete payload.folder;
        delete payload.sort;
        await actor.deleteEmbeddedDocuments("Item", [oldItem.id]);
        await actor.createEmbeddedDocuments("Item", [payload], { keepId: true });
      }
      stats.push(`${oldItem.name} → ${data.name}`);
    }

    for (const key of fix.addItems ?? []) {
      if (actor.items.find(i => i.system?.key === key)) continue;
      const data = await source(key);
      if (!data) { warn.push(`${actor.name}: не удалось добавить ${key}`); continue; }
      if (!DRY_RUN) {
        const payload = foundry.utils.deepClone(data);
        delete payload.folder;
        delete payload.sort;
        await actor.createEmbeddedDocuments("Item", [payload], { keepId: true });
      }
      stats.push(`добавлен ${data.name}`);
    }

    // HUD цепей показывает только избранные манёвры (chain-maneuvers-hud.mjs)
    if (fix.favoriteManeuvers) {
      let starred = 0;
      for (const item of actor.items.filter(i => i.type === "maneuver")) {
        if (item.getFlag("dedrel", "isFavorite")) continue;
        if (!DRY_RUN) await item.setFlag("dedrel", "isFavorite", true);
        starred++;
      }
      if (starred) stats.push(`манёвров в избранное: ${starred}`);
    }

    if (updates.length || renamed.length || orphans.length || wired.length || freed.length || stats.length) {
      const parts = [];
      if (updates.length) parts.push(`пересобрано предметов: ${updates.length}`);
      if (renamed.length) parts.push(`ключи: ${renamed.join(", ")}`);
      if (wired.length) parts.push(`связи талантов: ${wired.join(", ")}`);
      if (freed.length) parts.push(`освобождены слоты: ${freed.join(", ")}`);
      if (stats.length) parts.push(`стат-блок: ${stats.join("; ")}`);
      if (orphans.length) warn.push(`${actor.name}: не найдены в компендиумах — ${orphans.join(", ")}`);
      log.push(`<strong>${actor.name}</strong>: ${parts.join("; ")}`);
    }
  }

  if (!DRY_RUN && actorsLocked) await actorPack.configure({ locked: true });

  // ==========================================================================
  // ФАЗА 4: чистка устаревшего черновика «Удар лапой»
  // Удаляем, только если замена существует и на листах его больше нет.
  // ==========================================================================
  for (const [oldKey, newKey] of Object.entries(ALIASES)) {
    if (!index.has(newKey)) continue;
    const ref = index.get(oldKey);
    if (!ref) continue;
    const stillUsed = (await actorPack.getDocuments())
      .filter(a => a.items.find(i => i.system?.key === oldKey))
      .map(a => a.name);
    if (stillUsed.length) { warn.push(`${oldKey} ещё носят: ${stillUsed.join(", ")} — не удаляю`); continue; }
    const wasLocked = ref.pack.locked;
    if (!DRY_RUN) {
      if (wasLocked) await ref.pack.configure({ locked: false });
      await (await ref.pack.getDocument(ref.id)).delete();
      if (wasLocked) await ref.pack.configure({ locked: true });
    }
    log.push(`Из компендиума удалён устаревший «${oldKey}» (заменён на ${newKey})`);
  }

  const lines = [
    `<p><strong>Ремонт бестиария${DRY_RUN ? " (ТОЛЬКО ОТЧЁТ)" : ""}.</strong></p>`,
    log.length ? `<ul>${log.map(l => `<li>${l}</li>`).join("")}</ul>` : `<p>Расхождений не найдено.</p>`,
    warn.length ? `<p style="color:#a33"><strong>Внимание:</strong><br>${warn.join("<br>")}</p>` : ""
  ].filter(Boolean);

  await ChatMessage.create({ content: `<div class="dedrel-item-chat">${lines.join("")}</div>`, whisper: [game.user.id] });
  ui.notifications.info(`Ремонт бестиария: изменений ${log.length}, предупреждений ${warn.length}.`);
})();
